import json
from itertools import product

def solve():
    houses = [1, 2, 3, 4, 5, 6]

    categories = {
        "Name": ["Arnold", "Carol", "Eric", "Bob", "Alice", "Peter"],
        "birthday month": ["feb", "mar", "sept", "jan", "may", "april"],
        "lunch": ["stew", "soup", "grilled cheese", "stir fry", "spaghetti", "pizza"],
        "height": ["very short", "average", "super tall", "short", "very tall", "tall"],
        "car model": ["chevrolet silverado", "ford f150", "bmw 3 series", "tesla model 3", "toyota camry", "honda civic"],
    }

    # Create variables (one per attribute value)
    variables = []
    var_category = {}
    for cat, vals in categories.items():
        for v in vals:
            var = (cat, v)
            variables.append(var)
            var_category[var] = cat

    # Initialize domains
    domains = {var: set(houses) for var in variables}

    # Helper to reference variables
    def V(cat, val):
        return (cat, val)

    # Apply initial domain reductions from direct clues
    # 2. Ford F-150 in house 5
    domains[V("car model", "ford f150")] = {5}
    # 6. BMW 3 Series not in third house
    domains[V("car model", "bmw 3 series")] -= {3}
    # 10. Alice is directly left of BMW => BMW cannot be at 1; Alice cannot be at 6
    domains[V("car model", "bmw 3 series")] -= {1}
    domains[V("Name", "Alice")] -= {6}
    # 14. Stew not in third house
    domains[V("lunch", "stew")] -= {3}
    # 19. Very short in the fourth house
    domains[V("height", "very short")] = {4}
    # 15. One house between September and very short (which is at 4) => Sept at 2 or 6
    domains[V("birthday month", "sept")] &= {2, 6}
    # 5. Very short is left of April => April at 5 or 6 (since very short is at 4)
    domains[V("birthday month", "april")] &= {5, 6}
    # 8. Soup directly left of Eric => Soup not at 6; Eric not at 1
    domains[V("lunch", "soup")] -= {6}
    domains[V("Name", "Eric")] -= {1}
    # 13. Peter directly left of pizza => Peter not at 6; Pizza not at 1
    domains[V("Name", "Peter")] -= {6}
    domains[V("lunch", "pizza")] -= {1}
    # 11. Tesla left of tall => Tesla cannot be 6
    domains[V("car model", "tesla model 3")] -= {6}
    # 3. Stir fry left of Eric => Stir fry cannot be 6
    domains[V("lunch", "stir fry")] -= {6}

    # All-different groups by category
    groups = {cat: [V(cat, val) for val in vals] for cat, vals in categories.items()}

    # Constraints as a function
    def consistent(assignment):
        # All-different within categories
        for cat, vars_in_cat in groups.items():
            seen = {}
            for var in vars_in_cat:
                if var in assignment:
                    pos = assignment[var]
                    if pos in seen:
                        return False
                    seen[pos] = var

        # Helper to get pos if assigned
        def pos(var):
            return assignment.get(var, None)

        # 1. Honda Civic <-> short
        a, b = pos(V("car model", "honda civic")), pos(V("height", "short"))
        if a is not None and b is not None and a != b:
            return False

        # 2. Ford F-150 is in the fifth house
        a = pos(V("car model", "ford f150"))
        if a is not None and a != 5:
            return False

        # 3. Stir fry left of Eric
        a, b = pos(V("lunch", "stir fry")), pos(V("Name", "Eric"))
        if a is not None and b is not None and not (a < b):
            return False
        # 4. May left of Carol
        a, b = pos(V("birthday month", "may")), pos(V("Name", "Carol"))
        if a is not None and b is not None and not (a < b):
            return False
        # 5. Very short left of April
        a, b = pos(V("height", "very short")), pos(V("birthday month", "april"))
        if a is not None and b is not None and not (a < b):
            return False
        # 6. BMW 3 Series not in third house
        a = pos(V("car model", "bmw 3 series"))
        if a is not None and a == 3:
            return False
        # 7. Two houses between stir fry and pizza => distance 3
        a, b = pos(V("lunch", "stir fry")), pos(V("lunch", "pizza"))
        if a is not None and b is not None and abs(a - b) != 3:
            return False
        # 8. Soup directly left of Eric
        a, b = pos(V("lunch", "soup")), pos(V("Name", "Eric"))
        if a is not None and b is not None and not (a + 1 == b):
            return False
        # 9. Spaghetti and May are next to each other
        a, b = pos(V("lunch", "spaghetti")), pos(V("birthday month", "may"))
        if a is not None and b is not None and abs(a - b) != 1:
            return False
        # 10. Alice directly left of BMW 3 Series
        a, b = pos(V("Name", "Alice")), pos(V("car model", "bmw 3 series"))
        if a is not None and b is not None and not (a + 1 == b):
            return False
        # 11. Tesla left of tall
        a, b = pos(V("car model", "tesla model 3")), pos(V("height", "tall"))
        if a is not None and b is not None and not (a < b):
            return False
        # 12. Very tall <-> Toyota Camry
        a, b = pos(V("height", "very tall")), pos(V("car model", "toyota camry"))
        if a is not None and b is not None and a != b:
            return False
        # 13. Peter directly left of pizza
        a, b = pos(V("Name", "Peter")), pos(V("lunch", "pizza"))
        if a is not None and b is not None and not (a + 1 == b):
            return False
        # 14. Stew not in third house
        a = pos(V("lunch", "stew"))
        if a is not None and a == 3:
            return False
        # 15. One house between Sept and very short => distance 2
        a, b = pos(V("birthday month", "sept")), pos(V("height", "very short"))
        if a is not None and b is not None and abs(a - b) != 2:
            return False
        # 16. One house between March and super tall => distance 2
        a, b = pos(V("birthday month", "mar")), pos(V("height", "super tall"))
        if a is not None and b is not None and abs(a - b) != 2:
            return False
        # 17. Tall is Bob
        a, b = pos(V("height", "tall")), pos(V("Name", "Bob"))
        if a is not None and b is not None and a != b:
            return False
        # 18. May is to the right of Alice
        a, b = pos(V("Name", "Alice")), pos(V("birthday month", "may"))
        if a is not None and b is not None and not (a < b):
            return False
        # 19. Very short is in the fourth house
        a = pos(V("height", "very short"))
        if a is not None and a != 4:
            return False
        # 20. March is short
        a, b = pos(V("birthday month", "mar")), pos(V("height", "short"))
        if a is not None and b is not None and a != b:
            return False
        # 21. Carol is Tesla Model 3
        a, b = pos(V("Name", "Carol")), pos(V("car model", "tesla model 3"))
        if a is not None and b is not None and a != b:
            return False
        # 22. Eric is January
        a, b = pos(V("Name", "Eric")), pos(V("birthday month", "jan"))
        if a is not None and b is not None and a != b:
            return False

        # Additional feasibility checks for "left of" and "directly left" partial assignments:
        # If a variable must be left of another and one side assigned to boundary that makes it impossible, detect early.
        # For example, if we know A is directly left of B and A is 6 -> impossible; if B is 1 -> impossible, etc.

        # For each left-of pair, if one side assigned, ensure not impossible
        def left_of_feasible(a_var, b_var, direct=False):
            a_pos = pos(a_var)
            b_pos = pos(b_var)
            if a_pos is not None and b_pos is None:
                # If A is assigned at rightmost and needs to be left of someone
                if direct:
                    if a_pos == 6:
                        return False
                else:
                    if a_pos == 6:
                        return False
            if a_pos is None and b_pos is not None:
                # If B is assigned at leftmost and needs someone to the left
                if direct:
                    if b_pos == 1:
                        return False
                else:
                    if b_pos == 1:
                        return False
            if a_pos is not None and b_pos is not None:
                if direct:
                    return a_pos + 1 == b_pos
                else:
                    return a_pos < b_pos
            return True

        # Apply feasibility checks
        # 3. Stir fry left of Eric
        if not left_of_feasible(V("lunch", "stir fry"), V("Name", "Eric"), direct=False):
            return False
        # 8. Soup directly left of Eric
        if not left_of_feasible(V("lunch", "soup"), V("Name", "Eric"), direct=True):
            return False
        # 10. Alice directly left of BMW
        if not left_of_feasible(V("Name", "Alice"), V("car model", "bmw 3 series"), direct=True):
            return False
        # 11. Tesla left of tall
        if not left_of_feasible(V("car model", "tesla model 3"), V("height", "tall"), direct=False):
            return False
        # 13. Peter directly left of pizza
        if not left_of_feasible(V("Name", "Peter"), V("lunch", "pizza"), direct=True):
            return False
        # 5. very short left of April (though very short fixed at 4)
        if not left_of_feasible(V("height", "very short"), V("birthday month", "april"), direct=False):
            return False
        # 4. May left of Carol
        if not left_of_feasible(V("birthday month", "may"), V("Name", "Carol"), direct=False):
            return False

        return True

    # Backtracking with MRV heuristic and forward-checking on all-different
    def select_unassigned_var(assignment):
        unassigned = [v for v in variables if v not in assignment]
        # Minimum Remaining Values (MRV)
        best = None
        best_domain_size = None
        for v in unassigned:
            d = domains[v]
            # Filter domain by positions already used within same category
            used = {assignment[x] for x in groups[var_category[v]] if x in assignment}
            possible = d - used
            size = len(possible)
            if best is None or size < best_domain_size:
                best = v
                best_domain_size = size
        return best

    def order_domain_values(var, assignment):
        used = {assignment[x] for x in groups[var_category[var]] if x in assignment}
        return sorted(domains[var] - used)

    def backtrack(assignment):
        if len(assignment) == len(variables):
            if consistent(assignment):
                return assignment
            return None
        var = select_unassigned_var(assignment)
        for value in order_domain_values(var, assignment):
            assignment[var] = value
            if consistent(assignment):
                result = backtrack(assignment)
                if result is not None:
                    return result
            del assignment[var]
        return None

    solution_assignment = backtrack({})

    if solution_assignment is None:
        raise RuntimeError("No solution found")

    # Build rows per house
    header = ["House", "Name", "birthday month", "lunch", "height", "car model"]
    rows = []
    for house in houses:
        name = next(val for val in categories["Name"] if solution_assignment[V("Name", val)] == house)
        month = next(val for val in categories["birthday month"] if solution_assignment[V("birthday month", val)] == house)
        lunch = next(val for val in categories["lunch"] if solution_assignment[V("lunch", val)] == house)
        height = next(val for val in categories["height"] if solution_assignment[V("height", val)] == house)
        car = next(val for val in categories["car model"] if solution_assignment[V("car model", val)] == house)
        rows.append([str(house), name, month, lunch, height, car])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False, indent=2))
